import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Module-level font loading ensures font is ready before frame 0
const { fontFamily: playfairFamily } = loadPlayfair();



export type WealthTextAnimationProps = Record<string, any>;

const WealthTextAnimation: React.FC<WealthTextAnimationProps> = ({
  backgroundColor = "#080808",
  transparentBackground = false,
  durationInSeconds = 8,
  lines = [
    "Most people focus on building wealth.",
    "Very few focus on preserving it."
  ],
  highlightWords = ["wealth", "preserving"],
  textColor = "#f4f4f5",
  accentColor = "#d4af37", // Elegant gold accent
  wordStaggerFrames = 4,
  linePauseFrames = 45,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Ambient breathing scale for the entire container
  const totalFrames = Math.max(1, durationInSeconds * fps);
  const containerScale = interpolate(frame, [0, totalFrames], [0.95, 1.05], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: playfairFamily,
        justifyContent: "center",
        alignItems: "center",
        padding: `${height * 0.1}px ${width * 0.1}px`,
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transform: `scale(${containerScale})`,
          transition: "none",
        }}
      >
        {lines.map((line, lineIndex) => {
          const words = line.split(" ");
          
          return (
            <div
              key={lineIndex}
              style={{
                display: "flex",
                flexWrap: "wrap",
                justifyContent: "center",
                marginBottom: lineIndex === lines.length - 1 ? 0 : height * 0.04,
                maxWidth: width * 0.7,
                textAlign: "center",
                transition: "none",
              }}
            >
              {words.map((word, wordIndex) => {
                // Calculate timing based on both line index and word index
                const lineDelay = lineIndex * linePauseFrames;
                // Accumulate word delays from previous lines to maintain sequence logic
                const previousWordsCount = lines
                  .slice(0, lineIndex)
                  .reduce((acc, currLine) => acc + currLine.split(" ").length, 0);
                  
                const startFrame = lineDelay + (previousWordsCount + wordIndex) * wordStaggerFrames;
                const activeFrame = Math.max(0, frame - startFrame);

                const opacity = interpolate(activeFrame, [0, 20], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                });

                const translateY = interpolate(activeFrame, [0, 25], [30, 0], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: Easing.out(Easing.cubic),
                });

                // Match words ignoring punctuation (e.g., "wealth." -> "wealth")
                const cleanWord = word.replace(/[^a-zA-Z0-9]/g, "").toLowerCase();
                const isHighlighted = highlightWords.some(
                  (hw) => hw.replace(/[^a-zA-Z0-9]/g, "").toLowerCase() === cleanWord
                );

                return (
                  <span
                    key={`${lineIndex}-${wordIndex}`}
                    style={{
                      opacity,
                      transform: `translateY(${translateY}px)`,
                      display: "inline-block",
                      marginRight: "0.25em",
                      fontSize: height * 0.065,
                      lineHeight: 1.3,
                      color: isHighlighted ? accentColor : textColor,
                      fontWeight: isHighlighted ? 600 : 400,
                      fontStyle: isHighlighted ? "italic" : "normal",
                      transition: "none",
                    }}
                  >
                    {word}
                  </span>
                );
              })}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default WealthTextAnimation;